=== FILE: apb_gpio.v ===
// apb_gpio: general-purpose I/O behind an APB4 completer port.
// Implements interface_spec.md through microarchitecture.md.
// - Zero wait states: pready tied high, no state machine.
// - Synchronous, active-low reset (presetn); every flop is reset to zero.
// - All registers are 32 bits; bits N and up are held at zero by PINS.
module apb_gpio #(
    parameter integer ADDR_WIDTH = 8,
    parameter integer N          = 8
) (
    input  wire                  pclk,
    input  wire                  presetn,
    input  wire [ADDR_WIDTH-1:0] paddr,
    input  wire                  psel,
    input  wire                  penable,
    input  wire                  pwrite,
    input  wire [31:0]           pwdata,
    input  wire [3:0]            pstrb,
    output wire [31:0]           prdata,
    output wire                  pready,
    output wire                  pslverr,
    input  wire [N-1:0]          gpio_in,
    output wire [N-1:0]          gpio_out,
    output wire [N-1:0]          gpio_oe,
    output wire                  irq
);

  // Bits 0 to N-1 set.
  localparam [31:0] PINS = 32'hFFFF_FFFF >> (32 - N);

  // Register indices (paddr[5:2]).
  localparam [3:0] IDX_DATA_OUT    = 4'd0;
  localparam [3:0] IDX_DIR         = 4'd1;
  localparam [3:0] IDX_DATA_IN     = 4'd2;
  localparam [3:0] IDX_INTR_RISE   = 4'd3;
  localparam [3:0] IDX_INTR_FALL   = 4'd4;
  localparam [3:0] IDX_INTR_HIGH   = 4'd5;
  localparam [3:0] IDX_INTR_LOW    = 4'd6;
  localparam [3:0] IDX_INTR_ENABLE = 4'd7;
  localparam [3:0] IDX_INTR_STATUS = 4'd8;

  // ------------------------------------------------------------------
  // APB decode
  // ------------------------------------------------------------------
  wire        apb_access;
  wire [3:0]  idx;
  wire        addr_aligned;
  wire        addr_high_zero;
  wire        mapped;
  wire        wr_mapped;
  wire        rd_mapped;
  wire [31:0] wmask;

  assign apb_access     = psel & penable;
  assign idx            = paddr[5:2];
  assign addr_aligned   = (paddr[1:0] == 2'b00);
  assign addr_high_zero = (paddr[ADDR_WIDTH-1:6] == {(ADDR_WIDTH-6){1'b0}});
  assign mapped         = addr_aligned & addr_high_zero & (idx <= IDX_INTR_STATUS);
  assign wr_mapped      = apb_access & pwrite & mapped;
  assign rd_mapped      = apb_access & ~pwrite & mapped;
  assign wmask          = {{8{pstrb[3]}}, {8{pstrb[2]}}, {8{pstrb[1]}}, {8{pstrb[0]}}} & PINS;

  // ------------------------------------------------------------------
  // Input widened to 32 bits, zeros above N
  // ------------------------------------------------------------------
  wire [31:0] in_w;

  genvar g;
  generate
    for (g = 0; g < 32; g = g + 1) begin : g_in
      if (g < N) begin : g_pin
        assign in_w[g] = gpio_in[g];
      end else begin : g_nopin
        assign in_w[g] = 1'b0;
      end
    end
  endgenerate

  // ------------------------------------------------------------------
  // State
  // ------------------------------------------------------------------
  reg [31:0] data_out_q;
  reg [31:0] dir_q;
  reg [31:0] rise_en_q;
  reg [31:0] fall_en_q;
  reg [31:0] high_en_q;
  reg [31:0] low_en_q;
  reg [31:0] int_en_q;
  reg [31:0] status_q;
  reg [31:0] in_q;
  reg [31:0] in_prev_q;

  // Write enables
  wire we_data_out;
  wire we_dir;
  wire we_rise;
  wire we_fall;
  wire we_high;
  wire we_low;
  wire we_int_en;
  wire we_status;

  assign we_data_out = wr_mapped & (idx == IDX_DATA_OUT);
  assign we_dir      = wr_mapped & (idx == IDX_DIR);
  assign we_rise     = wr_mapped & (idx == IDX_INTR_RISE);
  assign we_fall     = wr_mapped & (idx == IDX_INTR_FALL);
  assign we_high     = wr_mapped & (idx == IDX_INTR_HIGH);
  assign we_low      = wr_mapped & (idx == IDX_INTR_LOW);
  assign we_int_en   = wr_mapped & (idx == IDX_INTR_ENABLE);
  assign we_status   = wr_mapped & (idx == IDX_INTR_STATUS);

  // Next state of the read/write registers: byte-merged write.
  wire [31:0] data_out_d;
  wire [31:0] dir_d;
  wire [31:0] rise_en_d;
  wire [31:0] fall_en_d;
  wire [31:0] high_en_d;
  wire [31:0] low_en_d;
  wire [31:0] int_en_d;

  assign data_out_d = we_data_out ? ((data_out_q & ~wmask) | (pwdata & wmask)) : data_out_q;
  assign dir_d      = we_dir      ? ((dir_q      & ~wmask) | (pwdata & wmask)) : dir_q;
  assign rise_en_d  = we_rise     ? ((rise_en_q  & ~wmask) | (pwdata & wmask)) : rise_en_q;
  assign fall_en_d  = we_fall     ? ((fall_en_q  & ~wmask) | (pwdata & wmask)) : fall_en_q;
  assign high_en_d  = we_high     ? ((high_en_q  & ~wmask) | (pwdata & wmask)) : high_en_q;
  assign low_en_d   = we_low      ? ((low_en_q   & ~wmask) | (pwdata & wmask)) : low_en_q;
  assign int_en_d   = we_int_en   ? ((int_en_q   & ~wmask) | (pwdata & wmask)) : int_en_q;

  // ------------------------------------------------------------------
  // Detection and status
  // ------------------------------------------------------------------
  wire [31:0] rise_ev;
  wire [31:0] fall_ev;
  wire [31:0] detected;
  wire [31:0] clear;
  wire [31:0] status_d;

  assign rise_ev  = in_q & ~in_prev_q;
  assign fall_ev  = ~in_q & in_prev_q;
  assign detected = ((rise_ev & rise_en_q) | (fall_ev & fall_en_q)
                    | (in_q & high_en_q) | (~in_q & low_en_q)) & PINS;
  assign clear    = we_status ? (pwdata & wmask) : 32'd0;
  // Detection is ORed last: a detection beats a clear on the same edge.
  assign status_d = (status_q & ~clear) | detected;

  // ------------------------------------------------------------------
  // Register block
  // ------------------------------------------------------------------
  always @(posedge pclk) begin
    if (!presetn) begin
      data_out_q <= 32'd0;
      dir_q      <= 32'd0;
      rise_en_q  <= 32'd0;
      fall_en_q  <= 32'd0;
      high_en_q  <= 32'd0;
      low_en_q   <= 32'd0;
      int_en_q   <= 32'd0;
      status_q   <= 32'd0;
      in_q       <= 32'd0;
      in_prev_q  <= 32'd0;
    end else begin
      data_out_q <= data_out_d;
      dir_q      <= dir_d;
      rise_en_q  <= rise_en_d;
      fall_en_q  <= fall_en_d;
      high_en_q  <= high_en_d;
      low_en_q   <= low_en_d;
      int_en_q   <= int_en_d;
      status_q   <= status_d;
      in_q       <= in_w;
      in_prev_q  <= in_q;
    end
  end

  // ------------------------------------------------------------------
  // Read data and response
  // ------------------------------------------------------------------
  reg [31:0] rd_mux;

  always @* begin
    case (idx)
      IDX_DATA_OUT:    rd_mux = data_out_q;
      IDX_DIR:         rd_mux = dir_q;
      IDX_DATA_IN:     rd_mux = in_q;
      IDX_INTR_RISE:   rd_mux = rise_en_q;
      IDX_INTR_FALL:   rd_mux = fall_en_q;
      IDX_INTR_HIGH:   rd_mux = high_en_q;
      IDX_INTR_LOW:    rd_mux = low_en_q;
      IDX_INTR_ENABLE: rd_mux = int_en_q;
      IDX_INTR_STATUS: rd_mux = status_q;
      default:         rd_mux = 32'd0;
    endcase
  end

  assign prdata  = rd_mapped ? rd_mux : 32'd0;
  assign pslverr = apb_access & (~mapped | (pwrite & (idx == IDX_DATA_IN)));
  assign pready  = 1'b1;

  // ------------------------------------------------------------------
  // Pins and interrupt
  // ------------------------------------------------------------------
  assign gpio_out = data_out_q[N-1:0];
  assign gpio_oe  = dir_q[N-1:0];
  assign irq      = |(status_q & int_en_q);

`ifdef FORMAL
  // Design-intent assertions (combinational response rules).
  always @(*) begin
    assert (pready == 1'b1);
    if (!apb_access) begin
      assert (prdata == 32'd0);
      assert (pslverr == 1'b0);
    end
    if (apb_access && pwrite) begin
      assert (prdata == 32'd0);
    end
  end
`endif

endmodule
=== END FILE ===
=== FILE: apb_gpio_tb.v ===
// apb_gpio_tb: self-checking directed testbench for apb_gpio.
// Two instances share one APB bus: dut8 (N = 8) and dut32 (N = 32).
// dut32 sees all 32 pins and dut8 the low 8, so every dut8 register equals
// the dut32 register masked to bits 7:0. Every check compares both.
// The bus and pins are driven at the falling edge (or just after a rising
// edge); the DUT samples them at the rising edge.
module apb_gpio_tb;

  localparam [7:0]  A_OUT  = 8'h00;
  localparam [7:0]  A_DIR  = 8'h04;
  localparam [7:0]  A_IN   = 8'h08;
  localparam [7:0]  A_RISE = 8'h0C;
  localparam [7:0]  A_FALL = 8'h10;
  localparam [7:0]  A_HIGH = 8'h14;
  localparam [7:0]  A_LOW  = 8'h18;
  localparam [7:0]  A_EN   = 8'h1C;
  localparam [7:0]  A_STAT = 8'h20;
  localparam [31:0] M8     = 32'h0000_00FF;

  reg         pclk;
  reg         presetn;
  reg  [7:0]  paddr;
  reg         psel;
  reg         penable;
  reg         pwrite;
  reg  [31:0] pwdata;
  reg  [3:0]  pstrb;
  reg  [31:0] gpio_in;

  wire [31:0] prdata8;
  wire [31:0] prdata32;
  wire        pready8;
  wire        pready32;
  wire        pslverr8;
  wire        pslverr32;
  wire [7:0]  gpio_out8;
  wire [7:0]  gpio_oe8;
  wire [31:0] gpio_out32;
  wire [31:0] gpio_oe32;
  wire        irq8;
  wire        irq32;

  integer passed;
  integer failed;
  integer phase;
  reg [8*64-1:0] nonce;

  apb_gpio #(.ADDR_WIDTH(8), .N(8)) dut8 (
    .pclk(pclk), .presetn(presetn), .paddr(paddr), .psel(psel),
    .penable(penable), .pwrite(pwrite), .pwdata(pwdata), .pstrb(pstrb),
    .prdata(prdata8), .pready(pready8), .pslverr(pslverr8),
    .gpio_in(gpio_in[7:0]), .gpio_out(gpio_out8), .gpio_oe(gpio_oe8),
    .irq(irq8)
  );

  apb_gpio #(.ADDR_WIDTH(8), .N(32)) dut32 (
    .pclk(pclk), .presetn(presetn), .paddr(paddr), .psel(psel),
    .penable(penable), .pwrite(pwrite), .pwdata(pwdata), .pstrb(pstrb),
    .prdata(prdata32), .pready(pready32), .pslverr(pslverr32),
    .gpio_in(gpio_in), .gpio_out(gpio_out32), .gpio_oe(gpio_oe32),
    .irq(irq32)
  );

  initial pclk = 1'b0;
  always #5 pclk = ~pclk;

  // ------------------------------------------------------------------
  // Checks
  // ------------------------------------------------------------------
  task chk32(input [31:0] got, input [31:0] want);
    begin
      if (got === want) begin
        passed = passed + 1;
      end else begin
        failed = failed + 1;
        $error("phase %0d: got %h, expected %h (time %0t)", phase, got, want, $time);
      end
    end
  endtask

  task chk1(input got, input want);
    begin
      if (got === want) begin
        passed = passed + 1;
      end else begin
        failed = failed + 1;
        $error("phase %0d: got %b, expected %b (time %0t)", phase, got, want, $time);
      end
    end
  endtask

  task check_pins(input [31:0] want_out, input [31:0] want_oe);
    begin
      chk32(gpio_out32, want_out);
      chk32({24'd0, gpio_out8}, want_out & M8);
      chk32(gpio_oe32, want_oe);
      chk32({24'd0, gpio_oe8}, want_oe & M8);
    end
  endtask

  task check_irq(input want32, input want8);
    begin
      chk1(irq32, want32);
      chk1(irq8, want8);
    end
  endtask

  task check_quiet;
    begin
      chk32(prdata32, 32'h0);
      chk32(prdata8, 32'h0);
      chk1(pslverr32, 1'b0);
      chk1(pslverr8, 1'b0);
    end
  endtask

  // ------------------------------------------------------------------
  // Stimulus helpers
  // ------------------------------------------------------------------
  task wait_cycles(input integer n);
    begin
      repeat (n) @(posedge pclk);
      #1;
    end
  endtask

  task set_pins(input [31:0] v);
    begin
      @(negedge pclk);
      gpio_in = v;
    end
  endtask

  task bus_idle;
    begin
      psel    = 1'b0;
      penable = 1'b0;
      pwrite  = 1'b0;
      paddr   = 8'h00;
      pwdata  = 32'h0;
      pstrb   = 4'h0;
    end
  endtask

  // A write. Ends just after its completing edge, so the next transfer's
  // setup follows directly (back-to-back).
  task apb_write(input [7:0] addr, input [31:0] data, input [3:0] strb, input exp_err);
    begin
      @(negedge pclk);
      psel    = 1'b1;
      penable = 1'b0;
      pwrite  = 1'b1;
      paddr   = addr;
      pwdata  = data;
      pstrb   = strb;
      #1;
      check_quiet;
      @(negedge pclk);
      penable = 1'b1;
      #1;
      chk1(pready32, 1'b1);
      chk1(pready8, 1'b1);
      chk1(pslverr32, exp_err);
      chk1(pslverr8, exp_err);
      chk32(prdata32, 32'h0);
      chk32(prdata8, 32'h0);
      @(posedge pclk);
      #1;
      bus_idle;
    end
  endtask

  // A read. want32 is the dut32 value; dut8 must return want32 & 0xFF.
  task apb_read(input [7:0] addr, input [31:0] want32, input exp_err);
    begin
      @(negedge pclk);
      psel    = 1'b1;
      penable = 1'b0;
      pwrite  = 1'b0;
      paddr   = addr;
      pwdata  = 32'h0;
      pstrb   = 4'h0;
      #1;
      check_quiet;
      @(negedge pclk);
      penable = 1'b1;
      #1;
      chk1(pready32, 1'b1);
      chk1(pready8, 1'b1);
      chk1(pslverr32, exp_err);
      chk1(pslverr8, exp_err);
      chk32(prdata32, want32);
      chk32(prdata8, want32 & M8);
      @(posedge pclk);
      #1;
      bus_idle;
    end
  endtask

  // Write, read back, and check the pins and irq (all other registers zero).
  task rw_step(input [7:0] addr, input [31:0] data, input [3:0] strb, input [31:0] want);
    begin
      apb_write(addr, data, strb, 1'b0);
      apb_read(addr, want, 1'b0);
      check_pins((addr == A_OUT) ? want : 32'h0, (addr == A_DIR) ? want : 32'h0);
      check_irq(1'b0, 1'b0);
    end
  endtask

  task rw_reg(input [7:0] addr);
    begin
      rw_step(addr, 32'hFFFF_FFFF, 4'b1111, 32'hFFFF_FFFF);
      rw_step(addr, 32'h0000_0000, 4'b0101, 32'hFF00_FF00);
      rw_step(addr, 32'hA5A5_A5A5, 4'b0010, 32'hFF00_A500);
      rw_step(addr, 32'h1234_5678, 4'b1000, 32'h1200_A500);
      rw_step(addr, 32'h0000_005A, 4'b0001, 32'h1200_A55A);
      rw_step(addr, 32'hFFFF_FFFF, 4'b0000, 32'h1200_A55A);
      rw_step(addr, 32'h0000_0000, 4'b1111, 32'h0000_0000);
    end
  endtask

  task read_all_zero_except_in(input [31:0] want_in);
    begin
      apb_read(A_OUT,  32'h0, 1'b0);
      apb_read(A_DIR,  32'h0, 1'b0);
      apb_read(A_IN,   want_in, 1'b0);
      apb_read(A_RISE, 32'h0, 1'b0);
      apb_read(A_FALL, 32'h0, 1'b0);
      apb_read(A_HIGH, 32'h0, 1'b0);
      apb_read(A_LOW,  32'h0, 1'b0);
      apb_read(A_EN,   32'h0, 1'b0);
      apb_read(A_STAT, 32'h0, 1'b0);
    end
  endtask

  // ------------------------------------------------------------------
  // Test sequence
  // ------------------------------------------------------------------
  initial begin
    passed  = 0;
    failed  = 0;
    phase   = 0;
    presetn = 1'b0;
    gpio_in = 32'h0;
    bus_idle;

    // ---- phase 1: reset
    phase = 1;
    repeat (3) @(posedge pclk);
    #1;
    check_pins(32'h0, 32'h0);
    check_irq(1'b0, 1'b0);
    check_quiet;
    @(negedge pclk);
    presetn = 1'b1;

    // ---- phase 2: reset values
    phase = 2;
    read_all_zero_except_in(32'h0);
    apb_write(A_STAT, 32'hFFFF_FFFF, 4'hF, 1'b0);
    apb_read(A_STAT, 32'h0, 1'b0);
    check_irq(1'b0, 1'b0);

    // ---- phase 3: read/write registers, strobes, bits above N, pins
    phase = 3;
    rw_reg(A_OUT);
    rw_reg(A_DIR);
    rw_reg(A_EN);
    rw_reg(A_RISE);
    rw_reg(A_FALL);
    rw_reg(A_HIGH);
    // Pins high so the low-level enable detects nothing while it is tested.
    set_pins(32'hFFFF_FFFF);
    wait_cycles(3);
    rw_reg(A_LOW);
    set_pins(32'h0);
    wait_cycles(3);
    apb_read(A_STAT, 32'h0, 1'b0);
    check_irq(1'b0, 1'b0);

    // ---- phase 4: DATA_IN, sampling latency, read only
    phase = 4;
    apb_read(A_IN, 32'h0, 1'b0);
    // A pin change driven during the access phase is sampled on the
    // completing edge, so this read still returns the old sample.
    @(negedge pclk);
    psel    = 1'b1;
    penable = 1'b0;
    pwrite  = 1'b0;
    paddr   = A_IN;
    pwdata  = 32'h0;
    pstrb   = 4'h0;
    @(negedge pclk);
    penable = 1'b1;
    gpio_in = 32'hC3C3_5AA5;
    #1;
    chk32(prdata32, 32'h0);
    chk32(prdata8, 32'h0);
    chk1(pslverr32, 1'b0);
    chk1(pslverr8, 1'b0);
    @(posedge pclk);
    #1;
    bus_idle;
    apb_read(A_IN, 32'hC3C3_5AA5, 1'b0);
    apb_write(A_IN, 32'h0000_0000, 4'hF, 1'b1);
    apb_read(A_IN, 32'hC3C3_5AA5, 1'b0);
    apb_write(A_IN, 32'hFFFF_FFFF, 4'h3, 1'b1);
    apb_read(A_IN, 32'hC3C3_5AA5, 1'b0);
    set_pins(32'h1234_5678);
    wait_cycles(2);
    apb_read(A_IN, 32'h1234_5678, 1'b0);
    set_pins(32'h0);
    wait_cycles(2);
    apb_read(A_IN, 32'h0, 1'b0);
    apb_read(A_STAT, 32'h0, 1'b0);

    // ---- phase 5: PSLVERR policy, unmapped and unaligned addresses
    phase = 5;
    apb_write(A_OUT, 32'h0F0F_0F0F, 4'hF, 1'b0);
    apb_write(8'h01, 32'hFFFF_FFFF, 4'hF, 1'b1);
    apb_write(8'h02, 32'hFFFF_FFFF, 4'hF, 1'b1);
    apb_write(8'h03, 32'hFFFF_FFFF, 4'hF, 1'b1);
    apb_write(8'h05, 32'hFFFF_FFFF, 4'hF, 1'b1);
    apb_write(8'h21, 32'hFFFF_FFFF, 4'hF, 1'b1);
    apb_write(8'h24, 32'hFFFF_FFFF, 4'hF, 1'b1);
    apb_write(8'h28, 32'hFFFF_FFFF, 4'hF, 1'b1);
    apb_write(8'h2C, 32'hFFFF_FFFF, 4'hF, 1'b1);
    apb_write(8'h30, 32'hFFFF_FFFF, 4'hF, 1'b1);
    apb_write(8'h34, 32'hFFFF_FFFF, 4'hF, 1'b1);
    apb_write(8'h38, 32'hFFFF_FFFF, 4'hF, 1'b1);
    apb_write(8'h3C, 32'hFFFF_FFFF, 4'hF, 1'b1);
    apb_write(8'h40, 32'hFFFF_FFFF, 4'hF, 1'b1);
    apb_write(8'h44, 32'hFFFF_FFFF, 4'hF, 1'b1);
    apb_write(8'h4C, 32'hFFFF_FFFF, 4'hF, 1'b1);
    apb_write(8'h80, 32'hFFFF_FFFF, 4'hF, 1'b1);
    apb_write(8'hA0, 32'hFFFF_FFFF, 4'hF, 1'b1);
    apb_write(8'hC0, 32'hFFFF_FFFF, 4'hF, 1'b1);
    apb_write(8'hDC, 32'hFFFF_FFFF, 4'hF, 1'b1);
    apb_write(8'hFC, 32'hFFFF_FFFF, 4'hF, 1'b1);
    apb_read(A_OUT,  32'h0F0F_0F0F, 1'b0);
    apb_read(A_DIR,  32'h0, 1'b0);
    apb_read(A_IN,   32'h0, 1'b0);
    apb_read(A_RISE, 32'h0, 1'b0);
    apb_read(A_FALL, 32'h0, 1'b0);
    apb_read(A_HIGH, 32'h0, 1'b0);
    apb_read(A_LOW,  32'h0, 1'b0);
    apb_read(A_EN,   32'h0, 1'b0);
    apb_read(A_STAT, 32'h0, 1'b0);
    check_pins(32'h0F0F_0F0F, 32'h0);
    check_irq(1'b0, 1'b0);
    apb_read(8'h01, 32'h0, 1'b1);
    apb_read(8'h02, 32'h0, 1'b1);
    apb_read(8'h03, 32'h0, 1'b1);
    apb_read(8'h22, 32'h0, 1'b1);
    apb_read(8'h24, 32'h0, 1'b1);
    apb_read(8'h3C, 32'h0, 1'b1);
    apb_read(8'h40, 32'h0, 1'b1);
    apb_read(8'h80, 32'h0, 1'b1);
    apb_read(8'hC0, 32'h0, 1'b1);
    apb_read(8'hFF, 32'h0, 1'b1);
    apb_write(A_OUT, 32'h0, 4'hF, 1'b0);
    check_pins(32'h0, 32'h0);

    // ---- phase 6: rising edge fires once; masked status still sets
    phase = 6;
    apb_write(A_RISE, 32'h8001_0003, 4'hF, 1'b0);
    set_pins(32'hFFFF_FFFF);
    wait_cycles(3);
    apb_read(A_STAT, 32'h8001_0003, 1'b0);
    check_irq(1'b0, 1'b0);
    apb_write(A_STAT, 32'hFFFF_FFFF, 4'hF, 1'b0);
    wait_cycles(3);
    apb_read(A_STAT, 32'h0, 1'b0);
    apb_write(A_RISE, 32'h0, 4'hF, 1'b0);
    set_pins(32'h0);
    wait_cycles(3);
    apb_read(A_STAT, 32'h0, 1'b0);

    // ---- phase 7: falling edge fires once
    phase = 7;
    apb_write(A_FALL, 32'h4000_0005, 4'hF, 1'b0);
    set_pins(32'hFFFF_FFFF);
    wait_cycles(3);
    apb_read(A_STAT, 32'h0, 1'b0);
    set_pins(32'h0);
    wait_cycles(3);
    apb_read(A_STAT, 32'h4000_0005, 1'b0);
    apb_write(A_STAT, 32'hFFFF_FFFF, 4'hF, 1'b0);
    wait_cycles(3);
    apb_read(A_STAT, 32'h0, 1'b0);
    apb_write(A_FALL, 32'h0, 4'hF, 1'b0);

    // ---- phase 8: high level sets again after a clear
    phase = 8;
    apb_write(A_HIGH, 32'h0010_0030, 4'hF, 1'b0);
    set_pins(32'h0010_0010);
    wait_cycles(3);
    apb_read(A_STAT, 32'h0010_0010, 1'b0);
    apb_write(A_STAT, 32'hFFFF_FFFF, 4'hF, 1'b0);
    apb_read(A_STAT, 32'h0010_0010, 1'b0);
    wait_cycles(3);
    apb_read(A_STAT, 32'h0010_0010, 1'b0);
    set_pins(32'h0);
    wait_cycles(3);
    apb_write(A_STAT, 32'hFFFF_FFFF, 4'hF, 1'b0);
    apb_read(A_STAT, 32'h0, 1'b0);
    apb_write(A_HIGH, 32'h0, 4'hF, 1'b0);

    // ---- phase 9: low level sets again after a clear
    phase = 9;
    set_pins(32'h0100_0040);
    wait_cycles(3);
    apb_write(A_LOW, 32'h0300_00C0, 4'hF, 1'b0);
    wait_cycles(3);
    apb_read(A_STAT, 32'h0200_0080, 1'b0);
    apb_write(A_STAT, 32'hFFFF_FFFF, 4'hF, 1'b0);
    apb_read(A_STAT, 32'h0200_0080, 1'b0);
    set_pins(32'hFFFF_FFFF);
    wait_cycles(3);
    apb_write(A_STAT, 32'hFFFF_FFFF, 4'hF, 1'b0);
    apb_read(A_STAT, 32'h0, 1'b0);
    apb_write(A_LOW, 32'h0, 4'hF, 1'b0);
    set_pins(32'h0);
    wait_cycles(3);
    apb_read(A_STAT, 32'h0, 1'b0);

    // ---- phase 10: write-1-to-clear of some bits only, by bit and strobe
    phase = 10;
    apb_write(A_RISE, 32'hFFFF_FFFF, 4'hF, 1'b0);
    set_pins(32'hFFFF_FFFF);
    wait_cycles(3);
    apb_read(A_STAT, 32'hFFFF_FFFF, 1'b0);
    apb_write(A_RISE, 32'h0, 4'hF, 1'b0);
    apb_write(A_STAT, 32'h0000_0005, 4'b1111, 1'b0);
    apb_read(A_STAT, 32'hFFFF_FFFA, 1'b0);
    apb_write(A_STAT, 32'hFFFF_FFFF, 4'b0010, 1'b0);
    apb_read(A_STAT, 32'hFFFF_00FA, 1'b0);
    apb_write(A_STAT, 32'h0000_0000, 4'b1111, 1'b0);
    apb_read(A_STAT, 32'hFFFF_00FA, 1'b0);
    apb_write(A_STAT, 32'hF0F0_F0F0, 4'b1100, 1'b0);
    apb_read(A_STAT, 32'h0F0F_00FA, 1'b0);
    apb_write(A_STAT, 32'hFFFF_FFFF, 4'b0000, 1'b0);
    apb_read(A_STAT, 32'h0F0F_00FA, 1'b0);
    check_irq(1'b0, 1'b0);
    apb_write(A_STAT, 32'hFFFF_FFFF, 4'b1111, 1'b0);
    apb_read(A_STAT, 32'h0, 1'b0);
    set_pins(32'h0);
    wait_cycles(3);
    apb_read(A_STAT, 32'h0, 1'b0);

    // ---- phase 11: interrupt mask
    phase = 11;
    apb_write(A_RISE, 32'h0001_0001, 4'hF, 1'b0);
    set_pins(32'h0001_0001);
    wait_cycles(3);
    apb_read(A_STAT, 32'h0001_0001, 1'b0);
    check_irq(1'b0, 1'b0);
    apb_write(A_EN, 32'h0001_0000, 4'hF, 1'b0);
    check_irq(1'b1, 1'b0);
    apb_read(A_EN, 32'h0001_0000, 1'b0);
    apb_write(A_EN, 32'h0000_0001, 4'hF, 1'b0);
    check_irq(1'b1, 1'b1);
    apb_write(A_EN, 32'h0, 4'hF, 1'b0);
    check_irq(1'b0, 1'b0);
    apb_read(A_STAT, 32'h0001_0001, 1'b0);
    apb_write(A_EN, 32'h0000_0002, 4'hF, 1'b0);
    check_irq(1'b0, 1'b0);
    apb_write(A_EN, 32'h0000_0003, 4'hF, 1'b0);
    check_irq(1'b1, 1'b1);
    apb_write(A_STAT, 32'h0000_0001, 4'hF, 1'b0);
    check_irq(1'b0, 1'b0);
    apb_read(A_STAT, 32'h0001_0000, 1'b0);
    apb_write(A_EN, 32'h0001_0000, 4'hF, 1'b0);
    check_irq(1'b1, 1'b0);
    apb_write(A_STAT, 32'hFFFF_FFFF, 4'hF, 1'b0);
    check_irq(1'b0, 1'b0);
    apb_write(A_EN, 32'h0, 4'hF, 1'b0);
    apb_write(A_RISE, 32'h0, 4'hF, 1'b0);
    set_pins(32'h0);
    wait_cycles(3);
    apb_read(A_STAT, 32'h0, 1'b0);

    // ---- phase 12: detection latency, and a detection beats a clear
    phase = 12;
    apb_write(A_RISE, 32'h0000_0003, 4'hF, 1'b0);
    apb_write(A_EN, 32'h0000_0001, 4'hF, 1'b0);
    check_irq(1'b0, 1'b0);
    @(negedge pclk);
    gpio_in = 32'h0000_0003;
    @(posedge pclk);          // edge E: pins sampled
    #1;
    check_irq(1'b0, 1'b0);
    @(posedge pclk);          // edge E+1: status set
    #1;
    check_irq(1'b1, 1'b1);
    apb_read(A_STAT, 32'h0000_0003, 1'b0);
    set_pins(32'h0);
    wait_cycles(3);
    apb_read(A_STAT, 32'h0000_0003, 1'b0);
    // Clear bits 0 and 1 while pin 0 rises: the rise is sampled on the
    // setup edge and detected on the completing edge, so bit 0 stays set
    // and bit 1 is cleared.
    @(negedge pclk);
    psel    = 1'b1;
    penable = 1'b0;
    pwrite  = 1'b1;
    paddr   = A_STAT;
    pwdata  = 32'h0000_0003;
    pstrb   = 4'hF;
    gpio_in = 32'h0000_0001;
    @(negedge pclk);
    penable = 1'b1;
    #1;
    chk1(pslverr32, 1'b0);
    chk1(pslverr8, 1'b0);
    @(posedge pclk);
    #1;
    bus_idle;
    apb_read(A_STAT, 32'h0000_0001, 1'b0);
    check_irq(1'b1, 1'b1);
    apb_write(A_STAT, 32'h0000_0001, 4'hF, 1'b0);
    apb_read(A_STAT, 32'h0, 1'b0);
    check_irq(1'b0, 1'b0);
    apb_write(A_RISE, 32'h0, 4'hF, 1'b0);
    apb_write(A_EN, 32'h0, 4'hF, 1'b0);
    set_pins(32'h0);
    wait_cycles(3);
    apb_read(A_STAT, 32'h0, 1'b0);

    // ---- phase 13: both edges enabled on one pin
    phase = 13;
    apb_write(A_RISE, 32'h0000_0008, 4'hF, 1'b0);
    apb_write(A_FALL, 32'h0000_0008, 4'hF, 1'b0);
    set_pins(32'h0000_0008);
    wait_cycles(3);
    apb_read(A_STAT, 32'h0000_0008, 1'b0);
    apb_write(A_STAT, 32'h0000_0008, 4'hF, 1'b0);
    wait_cycles(3);
    apb_read(A_STAT, 32'h0, 1'b0);
    set_pins(32'h0);
    wait_cycles(3);
    apb_read(A_STAT, 32'h0000_0008, 1'b0);
    apb_write(A_STAT, 32'h0000_0008, 4'hF, 1'b0);
    apb_read(A_STAT, 32'h0, 1'b0);
    apb_write(A_RISE, 32'h0, 4'hF, 1'b0);
    apb_write(A_FALL, 32'h0, 4'hF, 1'b0);

    // ---- phase 14: reset again
    phase = 14;
    apb_write(A_OUT, 32'hFFFF_FFFF, 4'hF, 1'b0);
    apb_write(A_DIR, 32'hA5A5_A5A5, 4'hF, 1'b0);
    apb_write(A_EN, 32'hFFFF_FFFF, 4'hF, 1'b0);
    apb_write(A_HIGH, 32'h0000_0001, 4'hF, 1'b0);
    set_pins(32'h0000_0001);
    wait_cycles(3);
    check_irq(1'b1, 1'b1);
    check_pins(32'hFFFF_FFFF, 32'hA5A5_A5A5);
    @(negedge pclk);
    presetn = 1'b0;
    @(posedge pclk);
    #1;
    check_pins(32'h0, 32'h0);
    check_irq(1'b0, 1'b0);
    check_quiet;
    wait_cycles(2);
    check_irq(1'b0, 1'b0);
    @(negedge pclk);
    presetn = 1'b1;
    read_all_zero_except_in(32'h0000_0001);
    check_pins(32'h0, 32'h0);
    check_irq(1'b0, 1'b0);
    set_pins(32'h0);
    wait_cycles(3);
    read_all_zero_except_in(32'h0);

    // ---- verdict
    if (!$value$plusargs("nirmaan_nonce=%s", nonce)) begin
      nonce = 512'd0;
    end
    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
    $finish;
  end

endmodule
